head.script:
scwin.log = function(msg) {
    var cur = txa_log.getValue();
    var ts = new Date().toLocaleTimeString();
    var line = "[" + ts + "] " + msg;
    txa_log.setValue(cur ? cur + "\n" + line : line);
};

scwin.onpageload = function() {
    scwin.log("WAEA-812 gridView exprColor/exprBackground 보존 테스트");
    scwin.log("- 첫 화면에 amount column의 color/bg가 즉시 적용되어야 함");
    scwin.log("- cell click 시 color는 유지, bg는 focus 색 (selectedCellColor) 으로 변경");
    scwin.log("- 다른 cell click 시 이전 cell의 color/bg가 복원되어야 함");

    var arr = [];
    for (var i = 0; i < 30; i++) {
        arr.push({
            status: i % 3 === 0 ? "A" : (i % 3 === 1 ? "R" : "P"),
            amount: i % 4 === 0 ? 20000 : 1000 + i * 100,
            balance: i % 2 === 0 ? -((i + 1) * 50) : (i + 1) * 50,
            name: "Item " + (i + 1)
        });
    }
    dataList1.setJSON(arr);
};

scwin.btn_verify_onclick = function() {
    scwin.log("=== 첫 화면 렌더링 검증 ===");
    var pass = 0;
    var fail = 0;

    function getTD(trIndex, colId) {
        var colIdx = grd1.tdIdList.indexOf(colId);
        if (colIdx < 0) return null;
        return grd1._getTDByIndex(trIndex * grd1.oneRowDataLength + colIdx);
    }

    var rowCount = dataList1.getRowCount();
    var visibleRows = grd1.lastIndex - grd1.rowIndex + 1;
    for (var r = 0; r < rowCount && r < visibleRows; r++) {
        var bal = Number(dataList1.getCellData(r, "balance"));
        var amt = Number(dataList1.getCellData(r, "amount"));
        var td = getTD(r, "amount");
        if (!td) continue;

        var expectColor = bal < 0 ? "rgb(255, 0, 0)" : "rgb(0, 0, 0)";
        if (td.style.color === expectColor) {
            pass++;
        } else {
            scwin.log("[FAIL] row" + r + " color expected " + expectColor + ", got '" + td.style.color + "'");
            fail++;
        }

        var expectBg = amt > 10000 ? "rgb(255, 204, 204)" : "rgb(255, 255, 255)";
        if (td.style.backgroundColor === expectBg) {
            pass++;
        } else {
            scwin.log("[FAIL] row" + r + " bg expected " + expectBg + ", got '" + td.style.backgroundColor + "'");
            fail++;
        }
    }
    scwin.log("=== 검증 종료 — PASS: " + pass + ", FAIL: " + fail + " ===");
};

scwin.btn_focus_test_onclick = function() {
    scwin.log("=== Focus 후 다른 cell focus 시 색상 복원 검증 ===");
    var pass = 0;
    var fail = 0;

    function getTD(trIndex, colId) {
        var colIdx = grd1.tdIdList.indexOf(colId);
        if (colIdx < 0) return null;
        return grd1._getTDByIndex(trIndex * grd1.oneRowDataLength + colIdx);
    }

    // row0의 amount (bal=-50, color=red, amt=20000, bg=#FFCCCC)
    var td0 = getTD(0, "amount");
    var beforeColor = td0.style.color;
    var beforeBg = td0.style.backgroundColor;
    scwin.log("row0 amount 초기 — color=" + beforeColor + ", bg=" + beforeBg);

    // row0 amount focus
    grd1.setFocusedCell(0, "amount");
    scwin.log("row0 amount focus 후 — color=" + td0.style.color + ", bg=" + td0.style.backgroundColor);

    // row0 의 color 는 유지되어야 함
    if (td0.style.color === beforeColor) {
        scwin.log("[PASS] focus 후 color 유지");
        pass++;
    } else {
        scwin.log("[FAIL] focus 후 color 손실");
        fail++;
    }

    // row1 amount focus → row0 의 color/bg 가 복원되어야 함
    grd1.setFocusedCell(1, "amount");
    scwin.log("row1 amount focus 후 — row0 color=" + td0.style.color + ", bg=" + td0.style.backgroundColor);

    if (td0.style.color === beforeColor) {
        scwin.log("[PASS] 다른 cell focus 후 이전 cell color 복원");
        pass++;
    } else {
        scwin.log("[FAIL] 다른 cell focus 후 이전 cell color 손실 (got '" + td0.style.color + "', expected '" + beforeColor + "')");
        fail++;
    }
    if (td0.style.backgroundColor === beforeBg) {
        scwin.log("[PASS] 다른 cell focus 후 이전 cell bg 복원");
        pass++;
    } else {
        scwin.log("[FAIL] 다른 cell focus 후 이전 cell bg 손실 (got '" + td0.style.backgroundColor + "', expected '" + beforeBg + "')");
        fail++;
    }

    scwin.log("=== Focus 검증 종료 — PASS: " + pass + ", FAIL: " + fail + " ===");
};
